-- Курс 94: Вайб-кодинг: создаём сайты, ботов и приложения с ИИ без опыта программирования. Редакционная программа, сразу готова к продаже.
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (94,'Вайб-кодинг: создаём сайты, ботов и приложения с ИИ без опыта программирования','vibecoding','adult',48,8,26,'Новый способ делать IT-продукты: вы описываете задачу словами, а нейросеть пишет код. Учимся работать с ИИ-инструментами разработки так, чтобы получался рабочий продукт, а не набор ошибок: ставить задачу, проверять и исправлять результат, подключать базу данных и оплату, выкладывать в интернет. За курс собираем лендинг, Telegram-бота, веб-приложение и сервис с личным кабинетом. 8 модулей, 48 уроков — и портфолио из четырёх продуктов.','["Создаёте сайты и веб-приложения, описывая задачу словами", "Ставите задачу нейросети так, чтобы код работал с первого-второго раза", "Находите и исправляете ошибки вместе с ИИ, понимая, что происходит", "Подключаете базу данных, авторизацию и приём оплаты", "Выкладываете проект в интернет на своём домене", "Собираете портфолио из 4 продуктов и берёте первые заказы"]'::jsonb,'Предприниматели, маркетологи, менеджеры продуктов, фрилансеры и все, кто хочет сам запускать сайты, ботов и сервисы без команды разработчиков. Опыт программирования не нужен.','["опыт программирования не требуется", "уверенная работа с компьютером", "идея продукта — плюс, но не обязательно"]'::jsonb,'Учимся на собственных проектах: каждый модуль заканчивается работающим продуктом. Теория — ровно столько, чтобы понимать, что делает ИИ и где он ошибается. ИИ-наставник помогает формулировать задачи и разбирать ошибки.','Итоговый проект: собственный веб-сервис с личным кабинетом, базой данных и оплатой, выложенный в интернет.',true,'editorial_manual',1,false,'18+');

INSERT INTO t_p78828167_tutor_platform_1.course_lessons (course_id,module_index,module_title,module_description,lesson_index,lesson_title,lesson_summary,lesson_type,estimated_minutes,topics,skills_acquired,homework_description,is_preview,sort_order)
SELECT 94,
  m.mi::int,
  m.mod->>'t',
  m.mod->>'d',
  l.li::int,
  l.les->>0,
  l.les->>1,
  l.les->>2,
  CASE l.les->>2 WHEN 'theory' THEN 30 WHEN 'project' THEN 45 ELSE 40 END,
  l.les->3,
  '[]'::jsonb,
  'Выполните задание урока «' || (l.les->>0) || '» и сохраните результат в портфолио курса.',
  (m.mi = 1 AND l.li = 1),
  ((m.mi - 1) * 6 + l.li)::int
FROM jsonb_array_elements('[{"t": "Модуль 1. Что такое вайб-кодинг", "d": "Новый способ создавать продукты и его границы.", "l": [["Вайб-кодинг: разработка словами", "Что изменилось в создании IT-продуктов.", "theory", ["Вайб-кодинг", "ИИ-разработка", "Продукт", "Скорость"]], ["Инструменты: обзор и выбор", "Конструкторы с ИИ, редакторы кода с ИИ, чат-модели.", "theory", ["Инструменты", "Редакторы", "Конструкторы", "Модели"]], ["Как устроен сайт и приложение", "Фронтенд, бэкенд, база данных — без сложных слов.", "theory", ["Фронтенд", "Бэкенд", "База данных", "Хостинг"]], ["Границы: что ИИ делает хорошо, а что плохо", "Где нужен человек и почему.", "theory", ["Ограничения", "Ошибки", "Безопасность", "Проверка"]], ["Рабочее место вайб-кодера", "Настраиваем инструменты и аккаунты.", "practice", ["Настройка", "Аккаунты", "Проекты", "Git"]], ["Практика: первая страница за 20 минут", "Описываем — получаем — правим.", "practice", ["Первая страница", "Описание", "Правки", "Публикация"]]]}, {"t": "Модуль 2. Как ставить задачу ИИ", "d": "Главный навык вайб-кодера.", "l": [["Техническое задание для нейросети", "Цель, пользователь, сценарии, ограничения.", "theory", ["ТЗ", "Цель", "Сценарии", "Ограничения"]], ["Работа по шагам", "Почему большой запрос ломает проект.", "theory", ["Декомпозиция", "Итерации", "Шаги", "Контроль"]], ["Как описывать дизайн", "Референсы, цвета, сетка, состояния.", "practice", ["Дизайн", "Референсы", "Цвета", "Адаптивность"]], ["Контекст проекта", "Как ИИ не забывал, что уже сделано.", "practice", ["Контекст", "Правила проекта", "Память", "Документация"]], ["Библиотека своих промптов", "Шаблоны задач, которые работают.", "practice", ["Шаблоны", "Промпты", "Библиотека", "Повтор"]], ["Практика: лендинг для бизнеса", "Полноценный продающий лендинг с формой заявки.", "practice", ["Лендинг", "Форма", "Блоки", "Публикация"]]]}, {"t": "Модуль 3. Читаем и исправляем код вместе с ИИ", "d": "Понимать достаточно, чтобы управлять.", "l": [["Как читать код без знания языка", "Структура файлов и что за что отвечает.", "theory", ["Код", "Файлы", "Структура", "Компоненты"]], ["Ошибки: где смотреть и как описать", "Консоль браузера и логи.", "practice", ["Ошибки", "Консоль", "Логи", "Описание"]], ["Отладка вместе с ИИ", "Пошаговый метод поиска причины.", "practice", ["Отладка", "Причина", "Гипотезы", "Проверка"]], ["Версии и откат", "Git простыми словами: как не потерять рабочую версию.", "practice", ["Git", "Версии", "Откат", "Ветки"]], ["Когда переписать, а когда чинить", "Как не утонуть в заплатках.", "theory", ["Рефакторинг", "Решение", "Технический долг", "Качество"]], ["Практика: починить сломанный проект", "Разбираем и исправляем ошибки по методу.", "practice", ["Практика", "Ошибки", "Исправление", "Тест"]]]}, {"t": "Модуль 4. Данные и пользователи", "d": "Продукт, который помнит пользователя.", "l": [["База данных простыми словами", "Таблицы, связи, зачем они нужны.", "theory", ["База данных", "Таблицы", "Связи", "Запросы"]], ["Подключаем базу к проекту", "Сохраняем заявки, товары, записи.", "practice", ["Подключение", "Сохранение", "Чтение", "Миграции"]], ["Регистрация и вход", "Личный кабинет пользователя.", "practice", ["Авторизация", "Регистрация", "Кабинет", "Сессии"]], ["Хранение файлов", "Загрузка фото и документов.", "practice", ["Файлы", "Загрузка", "Хранилище", "Ссылки"]], ["Безопасность данных", "Пароли, ключи, персональные данные и 152-ФЗ.", "theory", ["Безопасность", "Ключи", "Пароли", "152-ФЗ"]], ["Практика: сервис записи с кабинетом", "Клиент записывается, админ видит записи.", "practice", ["Запись", "Кабинет", "Админка", "База"]]]}, {"t": "Модуль 5. Боты и интеграции", "d": "Продукт, который общается и связывается с сервисами.", "l": [["Telegram-бот с ИИ", "Бот отвечает, принимает заявки и пишет в базу.", "practice", ["Telegram", "Бот", "Заявки", "База"]], ["Подключаем нейросеть к продукту", "ИИ-функции внутри вашего сервиса.", "practice", ["LLM", "API", "Функции", "Стоимость"]], ["Внешние сервисы по API", "Карты, почта, CRM, платёжки.", "practice", ["API", "Карты", "Почта", "CRM"]], ["Уведомления и рассылки", "Письма и сообщения из вашего продукта.", "practice", ["Уведомления", "Почта", "Сообщения", "Шаблоны"]], ["Автоматические задачи", "Что-то должно происходить по расписанию.", "practice", ["Расписание", "Фоновые задачи", "Напоминания", "Отчёты"]], ["Практика: бот-помощник для бизнеса", "Бот с ИИ, базой и уведомлениями.", "practice", ["Бот", "ИИ", "База", "Уведомления"]]]}, {"t": "Модуль 6. Оплата и запуск", "d": "Продукт, который зарабатывает.", "l": [["Приём оплаты", "ЮKassa, СБП, подписки — как подключить.", "practice", ["Оплата", "ЮKassa", "СБП", "Подписки"]], ["Свой домен и публикация", "Выкладываем проект в интернет.", "practice", ["Домен", "Хостинг", "SSL", "Публикация"]], ["SEO и скорость", "Чтобы сайт находили и он быстро открывался.", "practice", ["SEO", "Скорость", "Мета-теги", "Индексация"]], ["Аналитика", "Метрика и цели: что делают пользователи.", "practice", ["Метрика", "Цели", "Воронка", "Решения"]], ["Юридический минимум", "Оферта, политика конфиденциальности, согласия.", "theory", ["Оферта", "Политика", "Согласия", "Чеки"]], ["Практика: запуск с оплатой", "Платная функция в вашем продукте.", "practice", ["Запуск", "Оплата", "Проверка", "Публикация"]]]}, {"t": "Модуль 7. Продуктовое мышление", "d": "Делать то, что нужно людям.", "l": [["От идеи к MVP", "Минимальная версия, которую можно проверить.", "theory", ["MVP", "Гипотеза", "Проверка", "Приоритеты"]], ["Интервью с пользователями", "Как узнать, что людям правда нужно.", "practice", ["Интервью", "Боли", "Вопросы", "Выводы"]], ["Метрики продукта", "Что измерять, чтобы понимать рост.", "theory", ["Метрики", "Удержание", "Конверсия", "Рост"]], ["Обратная связь и итерации", "Улучшаем продукт по данным.", "practice", ["Обратная связь", "Итерации", "Приоритеты", "Релизы"]], ["Когда звать разработчика", "Признаки, что проект перерос вайб-кодинг.", "theory", ["Масштаб", "Команда", "Нагрузка", "Передача"]], ["Практика: улучшение по данным", "Находим узкое место и исправляем.", "practice", ["Анализ", "Узкое место", "Улучшение", "Результат"]]]}, {"t": "Модуль 8. Профессия и заказы", "d": "Как зарабатывать на вайб-кодинге.", "l": [["Кому нужны вайб-кодеры", "Малый бизнес, стартапы, агентства.", "theory", ["Заказчики", "Малый бизнес", "Стартапы", "Агентства"]], ["Услуги и цены", "Лендинг, бот, MVP — сколько брать.", "theory", ["Услуги", "Цены", "Пакеты", "Сроки"]], ["Портфолио из 4 продуктов", "Оформляем кейсы.", "practice", ["Портфолио", "Кейсы", "Демо", "Результаты"]], ["Переговоры и ТЗ с заказчиком", "Как не утонуть в правках.", "practice", ["Переговоры", "ТЗ", "Правки", "Договор"]], ["Поддержка проектов", "Абонентское обслуживание как стабильный доход.", "theory", ["Поддержка", "Абонемент", "Доработки", "Доход"]], ["Итоговый проект: свой веб-сервис", "Сервис с кабинетом, базой и оплатой — защита.", "project", ["Итоговый проект", "Сервис", "Оплата", "Защита"]]]}]'::jsonb) WITH ORDINALITY AS m(mod, mi)
CROSS JOIN LATERAL jsonb_array_elements(m.mod->'l') WITH ORDINALITY AS l(les, li);